def fizzbuzz() -> None:
    """Prints the FizzBuzz sequence from 1 to 100."""
    for num: int in range(1, 101):
        if num % 15 == 0:
            print("FizzBuzz")
        elif num % 3 == 0:
            print("Fizz")
        elif num % 5 == 0:
            print("Buzz")
        else:
            print(num)

from typing import List

def next_greater_element(nums: List[int]) -> List[int]:
    n: int = len(nums)
    res: List[int] = [-1] * n
    stack: List[int] = []

    for i in range(n - 1, -1, -1):
        while stack and stack[-1] <= nums[i]:
            stack.pop()
        if stack:
            res[i] = stack[-1]
        stack.append(nums[i])

    return res

def check_key(d, key):
    """Check recursively if a key exists in a nested dictionary."""
    if key in d:
        return True

    for value in d.values():
        if isinstance(value, dict):
            if check_key(value, key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    if check_key(item, key):
                        return True
    return False

from itertools import permutations

def get_permutations(s):
    return [''.join(p) for p in permutations(s)]

def decimal_to_binary(n: int) -> str:
    """
    Recursively converts a non-negative decimal integer into its binary string representation.

    Args:
        n: A non-negative integer to be converted.

    Returns:
        The binary representation of n as a string.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    def recursive_convert(num: int) -> str:
        if num == 0:
            return '0'
        elif num == 1:
            return '1'
        else:
            remainder = num % 2
            quotient = num // 2
            return recursive_convert(quotient) + ('0' if remainder == 0 else '1')

    return recursive_convert(n)

def fibonacci(n):
    if n <= 0:
        raise ValueError("Input must be a positive integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

def convert_temp(temp, mode):
    # Convert temperature based on mode: 'CtoF' or 'FtoC'
    if mode == 'CtoF':
        return (temp * 9/5) + 32  # Celsius to Fahrenheit formula
    elif mode == 'FtoC':
        return (temp - 32) * 5/9  # Fahrenheit to Celsius formula
    else:
        raise ValueError("Invalid mode. Use 'CtoF' or 'FtoC'.")

def get_valid_number(prompt):
    # Keep asking for input until a valid number is entered
    while True:
        try:
            value = float(input(prompt))
            return value
        except ValueError:
            print("Invalid input. Please enter a valid number.")

def main():
    print("Temperature Conversion Tool")

    # Get conversion mode from user
    mode = input("Enter conversion mode ('CtoF' or 'FtoC'): ")
    while mode not in ['CtoF', 'FtoC']:
        print("Invalid mode. Please enter 'CtoF' or 'FtoC'.")
        mode = input("Enter conversion mode: ")

    temp = get_valid_number("Enter temperature value: ")
    result = convert_temp(temp, mode)

    print(f"{temp} {'Celsius' if mode == 'CtoF' else 'Fahrenheit'} converted to {result} {'Fahrenheit' if mode == 'CtoF' else 'Celsius'}")

if __name__ == "__main__":
    main()

