def flatten_dict(nested_dict):
    flattened = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for subkey, subvalue in flatten_dict(value).items():
                flattened[f"{key}.{subkey}"] = subvalue
        else:
            flattened[key] = value
    return flattened

from typing import List

def sum_even_numbers(numbers: List[int]) -> int:
    """Return the sum of all even numbers in the input list."""
    sum_even = 0
    for num in numbers:
        if num % 2 == 0:
            sum_even += num
    return sum_even

def is_valid(s: str) -> bool:
    """Checks if the input string consists solely of lowercase letters and the punctuation marks: ',', '.', '!', '?'.

    Additionally, the string must contain at least one lowercase letter.

    Args:
        s: The input string to be validated.

    Returns:
        True if the string meets the criteria, False otherwise.
    """
    allowed_punctuation = {',', '.', '!', '?'}
    has_lowercase = False

    for char in s:
        if not (char.islower() or char in allowed_punctuation):
            return False
        if char.islower():
            has_lowercase = True

    return has_lowercase

def is_palindrome(s: str) -> bool:
    filtered = [c.lower() for c in s if c.isalpha()]
    return filtered == filtered[::-1]

def generate_strings(n):
    # Base case: empty string when length is 0
    if n == 0:
        return ['']
    result = []
    # Try all lowercase letters
    for char in 'abcdefghijklmnopqrstuvwxyz':
        # Recursively generate strings of length n-1
        for s in generate_strings(n - 1):
            # Ensure no consecutive duplicates
            if not s or s[-1] != char:
                result.append(char + s)
    return result
